parameters.jsCode:
const raw = $json.output;

let data;

if (typeof raw === 'string') {
  let text = raw.trim();

  // Remove markdown JSON fences if the model added them
  text = text.replace(/^```json\s*/i, '');
  text = text.replace(/^```\s*/i, '');
  text = text.replace(/\s*```$/i, '');

  data = JSON.parse(text);
} else {
  data = raw;
}

return {
  json: {
    phone: $('Edit Fields').item.json.phone,
    message: $('Edit Fields').first().json.Message,
    message_type: $('Edit Fields').first().json.Message_type,

    intent: data.intent || '',
    name: data.name || '',
    location: data.location || '',
    category: data.category || '',
    requirements: data.requirements || [],
    budget: data.budget || '',
    language: data.language || '',
    summary: data.summary || '',
    needs_human: data.needs_human || false
  }
};
